using System.Security.Cryptography;
using System.Text;
using DotCharter.Services.Export.Package;
using DotCharter.Services.Export.Sng;

namespace DotCharter.Tests.Services.Export;

/// <summary>
///     The three templates that used to be vendored files are generated in code (#894).
///     Each constant is the SHA-256 of the original file, which a byte-for-byte
///     comparison proved equal to the generated bytes before the file was deleted. So
///     these tests keep proving that a package carries exactly the bytes it always has.
/// </summary>
public class GeneratedGameTemplatesTests
{
    private const string RootSha256 = "93cf84b5116b905ba6cd9f6c9f2f04d52be2568c78c1b711d5cd45c414243e37";
    private const string SongSha256 = "f97cd48f6cdecbf8c8fdecd57908049b70b38165831e5deee51aef1f4fe92398";
    private const string SymbolsSha256 = "b5cbb44b10d89e12796201393a3409701c2ffacba589db55f8e4182a3a4a9fe7";

    private static string Sha256Hex(byte[] bytes) => Convert.ToHexStringLower(SHA256.HashData(bytes));

    private static byte[] SerializeSymbols()
    {
        var symbols = DefaultVocalSymbols.Load();
        using var memory = new MemoryStream();
        using var writer = new BinaryWriter(memory);
        writer.Write(symbols.Count);
        foreach (var symbol in symbols)
        {
            var glyph = new byte[12];
            Encoding.UTF8.GetBytes(symbol.Symbol, glyph);
            writer.Write(glyph);
            foreach (var value in symbol.Outer) writer.Write(value);
            foreach (var value in symbol.Inner) writer.Write(value);
        }

        return memory.ToArray();
    }

    [Fact]
    public void Root_flat_is_byte_identical_to_the_original_file() =>
        Assert.Equal(RootSha256, Sha256Hex(RsEnumerableModels.Root()));

    [Fact]
    public void Song_flat_is_byte_identical_to_the_original_file() =>
        Assert.Equal(SongSha256, Sha256Hex(RsEnumerableModels.Song()));

    [Fact]
    public void Vocal_symbol_table_is_byte_identical_to_the_original_file()
    {
        var bytes = SerializeSymbols();
        Assert.Equal(8452, bytes.Length);
        Assert.Equal(SymbolsSha256, Sha256Hex(bytes));
    }
}
